const STORAGE_KEY = 'saved_hotels_v1';

// Service Worker registrieren
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('./sw.js').catch(console.error);
  }

  // 1. Android Share-Target Parameter auslesen
  function parseSharedData() {
    const params = new URLSearchParams(window.location.search);
      const rawTitle = params.get('title') || '';
        const rawText = params.get('text') || '';
          const rawUrl = params.get('url') || '';

            const combined = `${rawTitle} ${rawText} ${rawUrl}`.trim();
              const urlMatch = combined.match(/https?:\/\/[^\s]+/i);

                if (urlMatch) {
                    document.getElementById('url').value = urlMatch[0];
                      }

                        // Versuche Hotelnamen aus Titel/Text zu extrahieren
                          const cleanedText = combined
                              .replace(/https?:\/\/[^\s]+/gi, '')
                                  .replace(/Schau dir dieses Hotel.*?an:?/i, '')
                                      .replace(/CHECK24/gi, '')
                                          .replace(/[|\-–]+$/g, '')
                                              .trim();

                                                if (cleanedText && !document.getElementById('hotelName').value) {
                                                    document.getElementById('hotelName').value = cleanedText;
                                                      }
                                                      }

                                                      // Hilfsfunktion: Sicherer JSON-Fetch (fängt 502/504 HTML-Fehlerseiten ab)
                                                      async function fetchJsonSafe(url, options = {}) {
                                                        const res = await fetch(url, options);
                                                          const text = await res.text();
                                                            if (!res.ok) {
                                                                throw new Error(`HTTP ${res.status}`);
                                                                  }
                                                                    try {
                                                                        return JSON.parse(text);
                                                                          } catch {
                                                                              throw new Error('Server lieferte kein gültiges JSON (vermutlich Überlastung)');
                                                                                }
                                                                                }

                                                                                // 2. Geocoding über Nominatim (erst Hotel + Ort, Fallback nur Ort)
                                                                                async function geocodeHotel(hotelName, location) {
                                                                                  const headers = { 'Accept-Language': 'de' };
                                                                                    const queries = [`${hotelName}, ${location}`, location];

                                                                                      for (const q of queries) {
                                                                                          try {
                                                                                                const data = await fetchJsonSafe(
                                                                                                        `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`,
                                                                                                                { headers }
                                                                                                                      );
                                                                                                                            if (data && data.length > 0) {
                                                                                                                                    return {
                                                                                                                                              lat: parseFloat(data[0].lat),
                                                                                                                                                        lon: parseFloat(data[0].lon),
                                                                                                                                                                  exact: q.includes(hotelName)
                                                                                                                                                                          };
                                                                                                                                                                                }
                                                                                                                                                                                    } catch (err) {
                                                                                                                                                                                          console.warn('Nominatim Versuch fehlgeschlagen:', q, err);
                                                                                                                                                                                              }
                                                                                                                                                                                                }
                                                                                                                                                                                                  throw new Error('Ort konnte auf OpenStreetMap nicht gefunden werden.');
                                                                                                                                                                                                  }

                                                                                                                                                                                                  // Haversine-Distanz in Metern
                                                                                                                                                                                                  function haversineMeters(lat1, lon1, lat2, lon2) {
                                                                                                                                                                                                    const R = 6371000;
                                                                                                                                                                                                      const toRad = (deg) => (deg * Math.PI) / 180;
                                                                                                                                                                                                        const dLat = toRad(lat2 - lat1);
                                                                                                                                                                                                          const dLon = toRad(lon2 - lon1);
                                                                                                                                                                                                            const a =
                                                                                                                                                                                                                Math.sin(dLat / 2) ** 2 +
                                                                                                                                                                                                                    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
                                                                                                                                                                                                                      return Math.round(R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                      // 3. Overpass API mit automatischem Mirror-Fallback bei 502/504
                                                                                                                                                                                                                      async function fetchNearbyGeo(lat, lon) {
                                                                                                                                                                                                                        const query = `
                                                                                                                                                                                                                            [out:json][timeout:15];
                                                                                                                                                                                                                                (
                                                                                                                                                                                                                                      nwr["aeroway"="aerodrome"]["iata"](around:120000,${lat},${lon});
                                                                                                                                                                                                                                            nwr["natural"="beach"](around:10000,${lat},${lon});
                                                                                                                                                                                                                                                  way["natural"="coastline"](around:10000,${lat},${lon});
                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                          out center;
                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                              const endpoints = [
                                                                                                                                                                                                                                                                  'https://overpass-api.de/api/interpreter',
                                                                                                                                                                                                                                                                      'https://overpass.kumi.systems/api/interpreter',
                                                                                                                                                                                                                                                                          'https://maps.mail.ru/osm/tools/overpass/api/interpreter'
                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                              let data = null;
                                                                                                                                                                                                                                                                                for (const endpoint of endpoints) {
                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                          data = await fetchJsonSafe(endpoint, {
                                                                                                                                                                                                                                                                                                  method: 'POST',
                                                                                                                                                                                                                                                                                                          body: `data=${encodeURIComponent(query)}`
                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                      if (data && data.elements) break;
                                                                                                                                                                                                                                                                                                                          } catch (err) {
                                                                                                                                                                                                                                                                                                                                console.warn(`Overpass Mirror ${endpoint} überlastet, wechsle...`, err.message);
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                        if (!data) {
                                                                                                                                                                                                                                                                                                                                            return { airport: null, beachMeters: null, failed: true };
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                let nearestAirport = null;
                                                                                                                                                                                                                                                                                                                                                  let minAirportDist = Infinity;
                                                                                                                                                                                                                                                                                                                                                    let minBeachDist = Infinity;

                                                                                                                                                                                                                                                                                                                                                      for (const el of data.elements || []) {
                                                                                                                                                                                                                                                                                                                                                          const elLat = el.lat ?? el.center?.lat;
                                                                                                                                                                                                                                                                                                                                                              const elLon = el.lon ?? el.center?.lon;
                                                                                                                                                                                                                                                                                                                                                                  if (!elLat || !elLon) continue;

                                                                                                                                                                                                                                                                                                                                                                      const dist = haversineMeters(lat, lon, elLat, elLon);

                                                                                                                                                                                                                                                                                                                                                                          if (el.tags?.aeroway === 'aerodrome' && el.tags?.iata) {
                                                                                                                                                                                                                                                                                                                                                                                if (dist < minAirportDist) {
                                                                                                                                                                                                                                                                                                                                                                                        minAirportDist = dist;
                                                                                                                                                                                                                                                                                                                                                                                                nearestAirport = {
                                                                                                                                                                                                                                                                                                                                                                                                          name: el.tags.name || el.tags.iata,
                                                                                                                                                                                                                                                                                                                                                                                                                    iata: el.tags.iata,
                                                                                                                                                                                                                                                                                                                                                                                                                              lat: elLat,
                                                                                                                                                                                                                                                                                                                                                                                                                                        lon: elLon
                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (el.tags?.natural === 'beach' || el.tags?.natural === 'coastline') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (dist < minBeachDist) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        minBeachDist = dist;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          airport: nearestAirport,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              beachMeters: minBeachDist === Infinity ? null : minBeachDist,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  failed: false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 4. OSRM: Echte Auto-Fahrtdauer zum Flughafen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    async function fetchDriveMinutes(fromLat, fromLon, toLat, toLon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const url = `https://router.project-osrm.org/route/v1/driving/${fromLon},${fromLat};${toLon},${toLat}?overview=false`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const data = await fetchJsonSafe(url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (data.routes && data.routes.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Math.round(data.routes[0].duration / 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.warn('OSRM Routing fehlgeschlagen:', err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Speicher-Helfer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function getHotels() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function saveHotels(list) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            renderList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function deleteHotel(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                list.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  saveHotels(list);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function renderList() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById('countBadge').textContent = list.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const container = document.getElementById('hotelList');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (list.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              container.innerHTML = '<p style="color:#94a3b8;font-size:0.85rem;">Noch keine Hotels gespeichert.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      container.innerHTML = list
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .map(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (h, i) => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="item-head">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>${h.hotelName} (${h.price ? h.price + ' €' : 'k. A.'})</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button class="btn-del" onclick="deleteHotel(${i})">✕</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="meta">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            📍 ${h.location} · ✈️ ${h.airportIata || '?'} (${h.airportMinutes !== '' ? h.airportMinutes + ' Min.' : '?'}) · 🏖️ ${h.beachMeters !== null && h.beachMeters !== '' ? h.beachMeters + ' m' : '?'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="meta">${h.board} · ${'⭐'.repeat(Number(h.rating))} ${h.notes ? '· ' + h.notes : ''}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 5. Formular-Submit
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById('hotelForm').addEventListener('submit', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const btn = document.getElementById('saveBtn');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const status = document.getElementById('status');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  btn.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const hotelName = document.getElementById('hotelName').value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const location = document.getElementById('location').value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status.textContent = '1/3 Suche Hotel-Koordinaten auf OpenStreetMap...';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const coords = await geocodeHotel(hotelName, location);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status.textContent = '2/3 Suche Flughafen & Strand in der Nähe...';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const geo = await fetchNearbyGeo(coords.lat, coords.lon);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let airportMinutes = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (geo.airport) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      status.textContent = `3/3 Berechne Fahrtdauer nach ${geo.airport.iata}...`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            airportMinutes = await fetchDriveMinutes(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    coords.lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            coords.lon,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    geo.airport.lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            geo.airport.lon
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const entry = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                datum: new Date().toLocaleDateString('de-DE'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      hotelName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            location,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  price: document.getElementById('price').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        board: document.getElementById('board').value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              rating: document.getElementById('rating').value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    travelDate: document.getElementById('travelDate').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          airportIata: geo.airport
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ? `${geo.airport.name} (${geo.airport.iata})`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : geo.failed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? 'OSM überlastet'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : 'Nicht gefunden',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    airportMinutes: airportMinutes ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          beachMeters: geo.beachMeters ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                exactMatch: coords.exact ? 'Exakt' : 'Ortszentrum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      notes: document.getElementById('notes').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            url: document.getElementById('url').value.trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        list.unshift(entry);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            saveHotels(list);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (geo.failed) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      status.textContent = '⚠️ Gespeichert (OSM-Server waren gerade überlastet, Geo-Werte leer).';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                status.textContent = `✅ Gespeichert! Flughafen: ${airportMinutes ?? '?'} Min. | Strand: ${geo.beachMeters ?? '>10000'} m`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        e.target.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            window.history.replaceState({}, document.title, './index.html');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  status.textContent = `❌ Fehler: ${err.message}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btn.disabled = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 6. CSV-Export & Android Share-Sheet (für OneDrive)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById('exportBtn').addEventListener('click', async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (list.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  alert('Keine Hotels zum Exportieren vorhanden.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const headers = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'Datum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'Hotel',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Ort',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'Preis_EUR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'Verpflegung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'Bewertung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Reisezeitraum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'Flughafen',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'Fahrtdauer_Flughafen_Min',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'Entfernung_Strand_m',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Geo_Genauigkeit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'Notiz',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'Check24_Link'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const escapeCsv = (val) => `"${String(val ?? '').replace(/"/g, '""')}"`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const rows = list.map((h) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              h.datum,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    h.hotelName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          h.location,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                h.price,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      h.board,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            h.rating,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  h.travelDate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        h.airportIata,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              h.airportMinutes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    h.beachMeters,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          h.exactMatch,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                h.notes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      h.url
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .map(escapeCsv)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .join(';')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const csvContent = '\uFEFF' + [headers.join(';'), ...rows].join('\n');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const file = new File([csvContent], 'check24_hotels.csv', { type: 'text/csv;charset=utf-8;' });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (navigator.canShare && navigator.canShare({ files: [file] })) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await navigator.share({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                title: 'Check24 Hotels CSV',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        files: [file]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (err.name === 'AbortError') return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const a = document.createElement('a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        a.href = URL.createObjectURL(file);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          a.download = 'check24_hotels.csv';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            a.click();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            parseSharedData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            renderList();